package com.example.solarfarm.controller;
import com.example.solarfarm.common.Dtos; import com.example.solarfarm.domain.User; import com.example.solarfarm.repository.UserRepository; import com.example.solarfarm.security.JwtService; import jakarta.validation.Valid; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/auth") public class AuthController { private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; public AuthController(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;} @PostMapping("/login") public Dtos.LoginResponse login(@Valid @RequestBody Dtos.LoginRequest request){User user=users.findByEmail(request.email()).orElseThrow(()->new IllegalArgumentException("Invalid credentials"));if(!encoder.matches(request.password(),user.getPasswordHash()))throw new IllegalArgumentException("Invalid credentials");return new Dtos.LoginResponse(jwt.generate(user.getEmail(),user.getRole().name()),"Bearer");} }
